#!/usr/bin/env node
/* ─── build-engineering-symbols ─────────────────────────────────────────────
 * Reads assets/engineering/*.svg + manifest.json and emits an inline React
 * module (dcmoc/.../diagram/symbols.gen.ts) exporting, per equipment kind, the
 * INNER SVG markup (paths/shapes) as a JSX-safe fragment string. Strokes stay
 * `currentColor` so the diagram recolours by lane. The generated fragment is
 * rendered inside a <g> that translate/scales the 0..48 symbol to any size.
 *
 * Run: node tools/build-engineering-symbols.mjs
 * GENERATED FILE — do not hand-edit symbols.gen.ts; edit the SVGs instead.
 * ──────────────────────────────────────────────────────────────────────── */
import { readFileSync, writeFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SRC = join(ROOT, 'assets', 'engineering');
const OUT = join(ROOT, 'dcmoc', 'src', 'components', 'modules', 'architecture', 'diagram', 'symbols.gen.ts');
const VIEW = 48; // authored viewBox is 0 0 48 48

const manifest = JSON.parse(readFileSync(join(SRC, 'manifest.json'), 'utf8'));

/** Extract the inner markup of an <svg> (drop wrapper + XML/HTML comments). */
function innerSvg(svg) {
    let s = svg.replace(/<!--[\s\S]*?-->/g, '');           // comments
    const open = s.indexOf('<svg');
    const gt = s.indexOf('>', open);
    const close = s.lastIndexOf('</svg>');
    s = s.slice(gt + 1, close);
    // normalise attribute names to JSX camelCase so the string can drop into JSX via dangerouslySetInnerHTML-free inlining
    return s.trim();
}

/** kebab/HTML attributes → keep as-is: we inject via innerHTML-compatible string,
 * so standard SVG attribute names (stroke-width, text-anchor…) are correct. */

const kinds = Object.keys(manifest);
const entries = kinds.map((kind) => {
    const meta = manifest[kind];
    const raw = readFileSync(join(SRC, meta.file), 'utf8');
    const body = innerSvg(raw)
        .replace(/\s+/g, ' ')
        .replace(/> </g, '><')
        .trim();
    return { kind, meta, body };
});

const header = `/* AUTO-GENERATED by tools/build-engineering-symbols.mjs — DO NOT EDIT.
 * Source: assets/engineering/*.svg + manifest.json.
 * Per equipment kind: the inner SVG markup (IEC single-line-diagram symbols),
 * strokes = currentColor so the diagram recolours by lane. Authored in a
 * 0..${VIEW} coordinate box; SymbolGlyph translate/scales it to any size. */

export const SYMBOL_VIEWBOX = ${VIEW};

export type GenSymbolKind =
${entries.map((e, i) => `    ${i === 0 ? '  ' : '| '}'${e.kind}'`).join('\n')};

export interface GenSymbolMeta { label: string; category: string }

export const SYMBOL_META: Record<GenSymbolKind, GenSymbolMeta> = {
${entries.map((e) => `    ${e.kind}: { label: ${JSON.stringify(e.meta.label)}, category: ${JSON.stringify(e.meta.category)} },`).join('\n')}
};

/** Inner SVG markup per kind (paths/shapes only; currentColor strokes). */
export const SYMBOL_MARKUP: Record<GenSymbolKind, string> = {
${entries.map((e) => `    ${e.kind}: ${JSON.stringify(e.body)},`).join('\n')}
};
`;

writeFileSync(OUT, header);
console.log(`symbols.gen.ts ← ${entries.length} symbols (${kinds.join(', ')})`);
